From 934f29bf862cc83b10f0cd6d56f35c2fe93f0b6c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:28:59 +0100
Subject: [PATCH] KIconEngine: return absolute paths unchanged from iconName()

For an icon made from an absolute file path, iconName() returned only the
file's base name, so Kirigami looked that name up in the icon theme and
Kickoff and KRunner showed a theme icon instead of the file. Keep the path.

BUG: 496178
---
 src/kiconengine.cpp | 5 +++++
 1 file changed, 5 insertions(+)

diff --git a/src/kiconengine.cpp b/src/kiconengine.cpp
index 10094de..25dfd15 100644
--- a/src/kiconengine.cpp
+++ b/src/kiconengine.cpp
@@ -12,6 +12,7 @@

 #include "kiconcolors.h"
 #include <KIconTheme>
+#include <QDir>
 #include <QFileInfo>
 #include <QPainter>
 #include <qscopeguard.h>
@@ -162,6 +163,10 @@ QString KIconEngine::iconName()
         return QString();
     }

+    if (QDir::isAbsolutePath(mIconName)) {
+        return mIconName;
+    }
+
     const QString iconPath = KIconLoaderPrivate::get(d->mIconLoader)->preferredIconPath(mIconName);
     if (iconPath.isEmpty()) {
         return QString();
-- 
